-- P99 Odus quests; faction prerequisites intentionally bypassed by IdleQuest policy.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Emote("looks down upon the creature standing beneath him and speaks. 'You are brave to approach a titan such as Giang Yin. I pray that the spirits have granted you honor and respect as well as courage.'")
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 6981 }) then
    e.self:Say("Your hammer has our blessing to free the souls from their crystalline shadow tombs.")
    e.other:SummonItem(6979)
    e.other:AddEXP(10000)
    e.other:Faction(473, 10, 0)
    e.other:Faction(298, 10, 0)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
